VERSION_NUM = "0.14.0"

# ---------------------------------------------------------------------------
# Resource (data/) access: works from a directory or from a zipapp archive.
# ---------------------------------------------------------------------------

def _archive_path():
    try:
        p = os.path.abspath(__file__)
    except Exception:
        return None
    # walk up looking for a zip file containing us
    cur = p
    while cur and cur != "/":
        if os.path.isfile(cur) and zipfile.is_zipfile(cur):
            return cur
        cur = os.path.dirname(cur)
    return None

_ZIP = None
_ZIP_TRIED = False

def _get_zip():
    global _ZIP, _ZIP_TRIED
    if _ZIP_TRIED:
        return _ZIP
    _ZIP_TRIED = True
    ap = _archive_path()
    if ap:
        try:
            _ZIP = zipfile.ZipFile(ap)
        except Exception:
            _ZIP = None
    return _ZIP

def _data_dir_fs():
    # directory containing this file, plus /data
    try:
        base = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        base = "."
    cand = os.path.join(base, "data")
    if os.path.isdir(cand):
        return cand
    # when running from workspace during development: src/data relative to cwd
    for c in ("src/data", "data", "./src/data"):
        if os.path.isdir(c):
            return c
    return cand

def data_read(relpath):
    """Return bytes for data/<relpath> or None."""
    z = _get_zip()
    if z is not None:
        for name in (f"data/{relpath}", relpath):
            try:
                return z.read(name)
            except KeyError:
                pass
        return None
    p = os.path.join(_data_dir_fs(), relpath)
    try:
        with open(p, "rb") as fh:
            return fh.read()
    except OSError:
        return None

def data_text(relpath, default=""):
    b = data_read(relpath)
    if b is None:
        return default
    return b.decode("utf-8", errors="surrogateescape")

def data_list(subdir):
    """List filenames (not paths) directly under data/<subdir>."""
    z = _get_zip()
    if z is not None:
        out = []
        prefix = f"data/{subdir}/"
        for n in z.namelist():
            if n.startswith(prefix):
                rest = n[len(prefix):]
                if rest and "/" not in rest:
                    out.append(rest)
        return sorted(out)
    d = os.path.join(_data_dir_fs(), subdir)
    try:
        return sorted(os.listdir(d))
    except OSError:
        return []

# ---------------------------------------------------------------------------
# Paths / home / work dir
# ---------------------------------------------------------------------------

def home_dir():
    # Reference: $HOME/.lnav if $HOME exists as a directory, else cwd.
    h = os.environ.get("HOME", "")
    if h and os.path.isdir(h):
        return os.path.join(h, ".lnav")
    return os.getcwd()

def work_dir():
    tmp = os.environ.get("TMPDIR") or "/tmp"
    try:
        uid = os.getuid()
    except Exception:
        uid = 1000
    return os.path.join(tmp, f"lnav-user-{uid}-work")

def binary_realpath(argv0):
    # Reference shows the resolved real path of the binary.
    try:
        # /proc/self/exe gives the python interpreter for us; prefer argv0 resolved.
        p = argv0 or sys.argv[0]
        return os.path.realpath(p)
    except Exception:
        return argv0

def ensure_home(argv0=None):
    """Create ~/.lnav structure and populate .sample files (once)."""
    hd = home_dir()
    try:
        os.makedirs(hd, exist_ok=True)
    except OSError:
        return hd
    for sub in ("configs/default", "configs/installed", "formats/default",
                "formats/installed", "staging", "crash"):
        try:
            os.makedirs(os.path.join(hd, sub), exist_ok=True)
        except OSError:
            pass
    # populate samples if missing (do not overwrite existing)
    for sub_src, sub_dst in (("formats", "formats/default"),
                             ("configs", "configs/default")):
        for name in data_list(sub_src):
            dst = os.path.join(hd, sub_dst, name)
            if os.path.exists(dst):
                continue
            content = data_read(f"{sub_src}/{name}")
            if content is None:
                continue
            try:
                with open(dst, "wb") as fh:
                    fh.write(content)
                # sample perms: read-only for .sample, exec for scripts - keep simple
                try:
                    if name.endswith(".sample"):
                        os.chmod(dst, 0o400)
                    elif name.endswith((".sh", ".py", ".lnav")):
                        os.chmod(dst, 0o500)
                except OSError:
                    pass
