# ---------------------------------------------------------------------------
# Time parsing helpers
# ---------------------------------------------------------------------------

MONTHS = {m: i + 1 for i, m in enumerate(
    ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"])}
MONTHS_FULL = {m: i + 1 for i, m in enumerate(
    ["January", "February", "March", "April", "May", "June", "July",
     "August", "September", "October", "November", "December"])}

def _try_formats(s, fmts):
    for f in fmts:
        try:
            return datetime.datetime.strptime(s, f)
        except Exception:
            continue
    return None

def parse_timestamp(s, ref_year=None):
    """Parse a wide variety of log timestamps. Return aware-ish naive UTC datetime or None."""
    if s is None:
        return None
    if isinstance(s, (int, float)):
        # epoch seconds or millis
        v = float(s)
        if v > 1e12:  # millis / micros heuristic
            v = v / 1000.0
        try:
            return datetime.datetime.utcfromtimestamp(v)
        except Exception:
            return None
    s = str(s).strip()
    if not s:
        return None
    # epoch numeric string
    if re.fullmatch(r"\d{10,13}(?:\.\d+)?", s):
        try:
            v = float(s)
            if len(s.split(".")[0]) > 10:
                v = v / (1000.0 ** (len(s.split(".")[0]) - 10 if False else 1)) if v > 1e11 else v
            if v > 1e12:
                v /= 1000.0
            return datetime.datetime.utcfromtimestamp(v)
        except Exception:
            pass
    # ISO-ish
    iso = s
    if iso.endswith("Z"):
        iso = iso[:-1] + "+00:00"
    # fix +0000 -> +00:00
    m = re.search(r"([+-]\d{2})(\d{2})$", iso)
    if m and ":" not in iso[m.start():]:
        iso = iso[:m.start()] + m.group(1) + ":" + m.group(2)
    try:
        dt = datetime.datetime.fromisoformat(iso)
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt
    except Exception:
        pass
    fmts = [
        "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
        "%Y/%m/%d %H:%M:%S.%f", "%Y/%m/%d %H:%M:%S", "%Y/%m/%d",
        "%Y-%m-%d", "%d/%b/%Y:%H:%M:%S %z", "%d/%b/%Y:%H:%M:%S",
        "%d/%b/%Y %H:%M:%S", "%d %b %Y %H:%M:%S", "%b %d %Y %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S.%f%z", "%Y-%m-%dT%H:%M:%S%z",
        "%a %b %d %H:%M:%S %Y", "%m/%d/%Y %H:%M:%S", "%m-%d-%Y %H:%M:%S",
        "%Y-%m-%d %H:%M:%S,%f", "%d-%b-%Y %H:%M:%S",
    ]
    dt = _try_formats(s, fmts)
    if dt is not None:
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt
    # syslog "Jun  3 10:00:00" (no year) - use current/system year
    m = re.match(r"^([A-Z][a-z]{2})\s+(\d{1,2})\s+(\d{2}):(\d{2}):(\d{2})(?:\.(\d+))?", s)
    if m and m.group(1) in MONTHS:
        year = ref_year or datetime.datetime.utcnow().year
        micro = 0
        if m.group(6):
            micro = int((m.group(6) + "000000")[:6])
        try:
            return datetime.datetime(year, MONTHS[m.group(1)], int(m.group(2)),
                                     int(m.group(3)), int(m.group(4)), int(m.group(5)), micro)
        except Exception:
            return None
    # "03/Jun/2024:10:00:00 +0000" handled above; also "2024-06-03 10:00:00.000+00:00" etc.
    # time only
    m = re.match(r"^(\d{2}):(\d{2}):(\d{2})(?:[.,](\d+))?$", s)
    if m:
        today = datetime.datetime.utcnow().date()
        micro = int(((m.group(4) or "") + "000000")[:6]) if m.group(4) else 0
        return datetime.datetime(today.year, today.month, today.day,
                                 int(m.group(1)), int(m.group(2)), int(m.group(3)), micro)
    return None

def parse_since_until(s):
    """Parse --since/--until / :goto / hide-lines values. Return datetime or None if invalid."""
    if s is None:
        return None
    txt = str(s).strip()
    if not txt:
        return None
    # relative like -1h, -2d, +1h? Reference accepts -1h.
    m = re.fullmatch(r"([+-]?\d+(?:\.\d+)?)([smhdw])", txt)
    if m:
        val = float(m.group(1))
        unit = m.group(2)
        secs = {"s": 1, "m": 60, "h": 3600, "d": 86400, "w": 604800}[unit]
        return datetime.datetime.utcnow() + datetime.timedelta(seconds=val * secs)
    if txt in ("now", "today", "yesterday"):
        now = datetime.datetime.utcnow()
        if txt == "now":
            return now
        if txt == "today":
            return now.replace(hour=0, minute=0, second=0, microsecond=0)
        return now.replace(hour=0, minute=0, second=0, microsecond=0) - datetime.timedelta(days=1)
    dt = parse_timestamp(txt)
    return dt

def fmt_log_time(dt):
    if dt is None:
        return None
    return dt.strftime("%Y-%m-%d %H:%M:%S.") + f"{dt.microsecond:06d}"

def fmt_iso_t(dt):
    if dt is None:
        return None
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond:06d}"

