# ---------------------------------------------------------------------------
# Log format definitions
# ---------------------------------------------------------------------------

LEVEL_ORDER = ["trace", "debug", "debug2", "debug3", "debug4", "debug5",
               "info", "stats", "notice", "warning", "error", "critical", "fatal"]
LEVEL_RANK = {n: i for i, n in enumerate(LEVEL_ORDER)}
# additional level spellings -> canonical
LEVEL_ALIASES = {
    "warn": "warning", "warning": "warning", "err": "error", "error": "error",
    "info": "info", "information": "info", "debug": "debug", "trace": "trace",
    "fatal": "fatal", "critical": "critical", "crit": "critical",
    "notice": "notice", "stats": "stats", "verbose": "trace",
}

def _convert_pattern(pat):
    """Convert PCRE-ish pattern from format JSON to Python re."""
    # (?<name>...) -> (?P<name>...)
    pat = re.sub(r"\(\?<([A-Za-z_][A-Za-z0-9_]*)>", r"(?P<\1>", pat)
    pat = re.sub(r"\(\?'([A-Za-z_][A-Za-z0-9_]*)'", r"(?P<\1>", pat)
    # atomic groups (?>...) -> (?:...)
    pat = pat.replace("(?>", "(?:")
    # possessive quantifiers: ++, *+, ?+, {m,n}+  -> drop trailing +
    pat = re.sub(r"(\+|\*|\?|\}\+)\+", lambda m: m.group(1).rstrip("+") if m.group(1) != "}" else "}", pat)
    # The above is rough; simpler passes:
    pat = pat.replace("++", "+").replace("*+", "*").replace("?+", "?")
    pat = re.sub(r"(\{\d+(?:,\d*)?\})\+", r"\1", pat)
    # \d{3}+ style leftovers
    return pat

def _sanitize_field(name):
    # Field names may contain '/', '-', '.' -> column names keep as-is? In schema
    # they appear verbatim (e.g. src/file). sqlite needs quoting; we store raw.
    return name

class LogFormat:
    def __init__(self, name, obj):
        self.name = name
        self.obj = obj or {}
        self.description = self.obj.get("description") or ""
        self.title = self.obj.get("title") or ""
        self.file_type = self.obj.get("file-type")  # 'json' or None
        self.is_json = (self.file_type == "json") or bool(self.obj.get("json")) or bool(self.obj.get("line-format"))
        # True JSON-lines formats have file-type json or 'json':true
        if self.obj.get("json") is True:
            self.is_json = True
        elif self.file_type == "json":
            self.is_json = True
        elif "line-format" in self.obj and "regex" not in self.obj:
            self.is_json = True
        else:
            # regex formats that also define line-format for display (journald) are JSON too
            if "regex" not in self.obj and "line-format" in self.obj:
                self.is_json = True
            elif "regex" in self.obj:
                self.is_json = False
        self.multiline = self.obj.get("multiline", True)
        self.ordered = self.obj.get("ordered-by-time", True)
        self.timestamp_field = self.obj.get("timestamp-field") or self.obj.get("time-field") or "timestamp"
        self.body_field = self.obj.get("body-field") or "body"
        self.level_field = self.obj.get("level-field")
        self.level_map = self.obj.get("level") or {}
        self.value_defs = self.obj.get("value") or {}
        self.search_tables = self.obj.get("search-table") or {}
        self.samples = self.obj.get("sample") or []
        self.line_format = self.obj.get("line-format")
        self.opid_field = self.obj.get("opid-field")
        self.thread_field = self.obj.get("thread-id-field")
        self.src_file_field = self.obj.get("src-file-field")
        self.src_line_field = self.obj.get("src-line-field")
        self.file_pattern = self.obj.get("file-pattern")
        # compiled regexes: list of (rname, compiled, original_pattern)
        self.regexes = []
        for rname, robj in (self.obj.get("regex") or {}).items():
            pat = robj.get("pattern", "") if isinstance(robj, dict) else str(robj)
            try:
                compiled = re.compile(_convert_pattern(pat))
            except Exception:
                # fallback: try loosening problematic {n}+ etc.
                try:
                    p2 = _convert_pattern(pat).replace("{3}+", "{3}").replace("}+", "}")
                    compiled = re.compile(p2)
                except Exception:
                    continue
            self.regexes.append((rname, compiled, pat))
        # value columns sorted alphabetically, excluding hidden
        self.columns = []  # list of (colname, kind)
        for fname in sorted(self.value_defs.keys()):
            vdef = self.value_defs[fname] or {}
            if vdef.get("hidden"):
                continue
            kind = (vdef.get("kind") or "string").lower()
            self.columns.append((fname, kind))

    def compute_level(self, fields, body_text):
        # fields: dict of captured groups / json values
        lf = self.level_field
        raw = None
        if lf:
            raw = fields.get(lf)
            if raw is None and lf == "body":
                raw = body_text
        if self.level_map:
            # order matters? Reference checks each level pattern; return first match
            # in a severity-ish order? Empirically syslog: error checked before warning.
            # Use insertion order of the JSON object (Python preserves it).
            for lvl, pat in self.level_map.items():
                if isinstance(pat, (int, float)):
                    try:
                        if raw is not None and float(raw) == float(pat):
                            return lvl
                    except Exception:
                        if str(raw) == str(pat):
                            return lvl
                    continue
                if raw is None:
                    continue
                try:
                    if re.search(_convert_pattern(str(pat)), str(raw)):
                        return lvl
                except Exception:
                    if str(pat) in str(raw):
                        return lvl
            # fall through to generic detection if level-field looks like a level word
        # Generic fallback: look at level-ish fields, body keywords
        for key in ("level", "log_level", "severity", "lvl"):
            v = fields.get(key)
            if isinstance(v, str) and v.lower() in LEVEL_ALIASES:
                return LEVEL_ALIASES[v.lower()]
            if isinstance(v, str) and v.lower() in LEVEL_RANK:
                return v.lower()
        if raw is not None and isinstance(raw, str):
            low = raw.strip().lower()
            if low in LEVEL_ALIASES:
                return LEVEL_ALIASES[low]
            if low in LEVEL_RANK:
                return low
            # numeric syslog priority style
        # Body keyword heuristic (used by generic/syslog-like)
        txt = body_text or ""
        if re.search(r"(?<![A-Za-z])(?i:error)(?![A-Za-z])|failed|failure", txt):
            # Only apply for formats without explicit levels? syslog needs it.
            if self.name in ("syslog_log", "generic_log") or not self.level_map:
                return "error"
        if re.search(r"(?i:warn)", txt):
            if self.name in ("syslog_log", "generic_log") or not self.level_map:
                return "warning"
        return "info"

