def read_file_bytes(path):
    # handle compressed by extension
    lower = path.lower()
    try:
        if lower.endswith(".gz"):
            with gzip.open(path, "rb") as fh:
                return fh.read()
        if lower.endswith(".bz2"):
            with bz2.open(path, "rb") as fh:
                return fh.read()
        if lower.endswith(".xz"):
            import lzma
            with lzma.open(path, "rb") as fh:
                return fh.read()
        with open(path, "rb") as fh:
            return fh.read()
    except OSError:
        raise

def decode_lines(raw_bytes):
    text = raw_bytes.decode("utf-8", errors="surrogateescape")
    # splitlines handles \n; preserve no trailing empty from final newline?
    # Reference counts lines as in file. Use split on \n keeping logic:
    if text == "":
        return []
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    # strip trailing \r
    lines = [l[:-1] if l.endswith("\r") else l for l in lines]
    return lines

def _json_lookup(obj, field):
    # field may be 'a/b' or '/a/b' or 'a.b'
    if obj is None or field is None:
        return None
    if field in obj:
        return obj[field]
    parts = [p for p in re.split(r"[/.]", field) if p]
    cur = obj
    for p in parts:
        if isinstance(cur, dict) and p in cur:
            cur = cur[p]
        else:
            return None
    return cur

def _flatten_json(obj, prefix="", out=None):
    if out is None:
        out = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            key = f"{prefix}/{k}" if prefix else k
            out[key] = v if not isinstance(v, (dict, list)) else (
                json.dumps(v, separators=(",", ":"), ensure_ascii=False) if isinstance(v, list) else v)
            if isinstance(v, dict):
                _flatten_json(v, key, out)
    return out

def try_parse_json_line(line):
    s = line.strip()
    if not s.startswith("{"):
        return None
    try:
        obj = json.loads(s)
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    return obj

def detect_format(lines, formats, filename=""):
    """Return (format_name, LogFormat) or (None, None)."""
    if not lines:
        return (None, None)
    # Sample first few non-empty lines (reference appears to use early lines)
    sample = []
    for l in lines:
        if l.strip():
            sample.append(l)
        if len(sample) >= 10:
            break
    if not sample:
        return (None, None)
    # JSON-lines detection
    json_objs = [try_parse_json_line(l) for l in sample]
    if json_objs and all(o is not None for o in json_objs[:3] if True) and json_objs[0] is not None:
        # Score JSON formats by whether their timestamp+body/value fields exist
        best = None
        best_score = -1
        for name, fmt in formats.items():
            if not fmt.is_json:
                continue
            score = 0
            obj = json_objs[0]
            flat = _flatten_json(obj)
            ts = _json_lookup(obj, fmt.timestamp_field) if fmt.timestamp_field else None
            if ts is not None:
                score += 3
            # value field presence
            hits = sum(1 for (col, kind) in fmt.columns if _json_lookup(obj, col) is not None or col in flat)
            # also count hidden value defs
            hits += sum(1 for col in fmt.value_defs if _json_lookup(obj, col) is not None)
            score += hits
            if fmt.body_field and _json_lookup(obj, fmt.body_field) is not None:
                score += 2
            if score > best_score:
                best_score = score
                best = (name, fmt)
        if best is not None and best_score >= 3:
            return best
        # Generic JSON handling: look for time/level/msg-ish keys -> use a synthetic
        # handling via generic_log? Reference renders such files as log messages.
        # We map them to a pseudo-format stored as generic handling in caller:
        # return special name handled by parse as JSON-generic.
        obj = json_objs[0]
        keys_lower = {k.lower(): k for k in obj.keys()}
        has_time = any(k in keys_lower for k in ("time", "timestamp", "ts", "@timestamp", "datetime", "date"))
        if has_time:
            return ("__json_generic__", None)
    # Regex formats: score by matched sample lines; prefer non-generic, longer patterns
    best = None
    best_key = None
    for name, fmt in formats.items():
        if fmt.is_json or not fmt.regexes:
            continue
        if fmt.file_pattern:
            try:
                if not re.search(fmt.file_pattern, filename):
                    # still allow but deprioritize
                    pass
            except Exception:
                pass
        matched = 0
        total_pat_len = 0
        for l in sample:
            for (rname, compiled, orig) in fmt.regexes:
                if compiled.match(l):
                    matched += 1
                    total_pat_len += len(orig)
                    break
        if matched == 0:
            continue
        ratio = matched / len(sample)
        # generic_log deprioritized
        is_generic = 1 if name in ("generic_log", "lnav_piper_log", "logfmt_log") else 0
        key = (matched, -is_generic, total_pat_len)
        if best_key is None or key > best_key:
            best_key = key
            best = (name, fmt)
    if best is not None:
        # Require at least first line matches? Reference: file with no format if
        # early lines don't match. Be lenient: require matched >=1 and first line matched
        name, fmt = best
        first_ok = any(c.match(sample[0]) for (_, c, _) in fmt.regexes)
        if first_ok:
            return best
        # if most lines match, still accept
        if best_key[0] >= max(1, len(sample) // 2):
            return best
    return (None, None)

def parse_log_lines(loaded, fmt, fmt_name):
    """Populate loaded.messages from loaded.lines using fmt. Returns messages."""
    msgs = []
    if fmt_name == "__json_generic__" or (fmt is not None and fmt.is_json):
        # JSON lines
        for idx, line in enumerate(loaded.lines):
            obj = try_parse_json_line(line)
            if obj is None:
                # continuation / non-json appended to previous body
                if msgs:
                    msgs[-1].body = (msgs[-1].body + "\n" + line) if msgs[-1].body else line
                    msgs[-1].text += "\n" + line
                    msgs[-1].raw += "\n" + line
                continue
            msg = LogMessage()
            msg.line_no = idx
            msg.path = loaded.filepath
            msg.fmt_name = fmt_name if fmt_name != "__json_generic__" else None
            flat = _flatten_json(obj)
            fields = {}
            for k, v in flat.items():
                fields[k] = v
            msg.fields = fields
            # timestamp
