                            "__REALTIME_TIMESTAMP", "t"]
            for cf in cand_fields:
                v = _json_lookup(obj, cf)
                if v is not None:
                    ts_raw = v
                    ts_field_used = cf
                    break
            # timestamp-divisor (e.g. pino epoch millis)
            dt = None
