                    divisor = fmt.obj.get("timestamp-divisor")
                if isinstance(ts_raw, (int, float)) and divisor:
                    try:
                        dt = datetime.datetime.utcfromtimestamp(float(ts_raw) / float(divisor) * (1000.0 if float(divisor) == 1000 else 1) / (1000.0 if float(divisor) == 1000 else 1))
                        # Simpler: divisor semantics unclear; handle millis: time is epoch ms with divisor 1000?
                        dt = datetime.datetime.utcfromtimestamp(float(ts_raw) / 1000.0) if float(ts_raw) > 1e12 else parse_timestamp(ts_raw)
                    except Exception:
                        dt = parse_timestamp(ts_raw)
                elif isinstance(ts_raw, dict):
                    # mongodb {"$date": "..."} 
                    inner = ts_raw.get("$date") or ts_raw.get("iso") or str(ts_raw)
                    dt = parse_timestamp(inner)
                else:
                    dt = parse_timestamp(ts_raw)
            msg.time = dt
            # body
            body = None
            if fmt is not None and fmt.body_field:
                body = _json_lookup(obj, fmt.body_field)
            if body is None:
                for bf in ("msg", "message", "MESSAGE", "body", "log", "event"):
                    if bf in obj:
                        body = obj[bf]
                        break
            if body is None:
                body = line
            msg.body = str(body) if not isinstance(body, str) else body
            # level
            if fmt is not None:
                msg.level = fmt.compute_level(fields, msg.body)
            else:
                lvl_raw = None
                for lk in ("level", "lvl", "severity", "PRIORITY", "s"):
                    if lk in obj:
                        lvl_raw = obj[lk]
                        break
                if isinstance(lvl_raw, str) and lvl_raw.lower() in LEVEL_ALIASES:
                    msg.level = LEVEL_ALIASES[lvl_raw.lower()]
                elif isinstance(lvl_raw, str) and lvl_raw.lower() in LEVEL_RANK:
                    msg.level = lvl_raw.lower()
                elif isinstance(lvl_raw, (int, float)):
                    # bunyan/pino style numbers
                    mapping = {60: "fatal", 50: "error", 40: "warning", 30: "info", 20: "debug", 10: "trace"}
                    msg.level = mapping.get(int(lvl_raw), "info")
                else:
                    msg.level = "info"
            msg.raw = line
            # display text: rendered line-format or generic rendering
            msg.text = render_json_line(obj, fmt, msg, ts_raw)
            # opid / thread
            if fmt is not None and fmt.thread_field:
                tv = _json_lookup(obj, fmt.thread_field)
                msg.thread_id = str(tv) if tv is not None else None
            if fmt is not None and fmt.opid_field:
                ov = _json_lookup(obj, fmt.opid_field)
                msg.opid = str(ov) if ov is not None else None
            msgs.append(msg)
        return msgs
    # Regex format
    assert fmt is not None
    for idx, line in enumerate(loaded.lines):
        matched = None
