# ---------------------------------------------------------------------------
# Table (SQL result) formatting
# ---------------------------------------------------------------------------

def format_sql_value(v):
    if v is None:
        return "<NULL>"
    if isinstance(v, bytes):
        try:
            s = v.decode("utf-8")
        except Exception:
            s = v.decode("utf-8", errors="replace")
        return s.replace("\n", "␊")
    if isinstance(v, float):
