def expand_vars(text, script_args):
    """Expand $VAR, ${VAR}, $1.. in command text (outside single quotes? reference expands in :echo)."""
    def repl(m):
        braced = m.group(1) if m.group(1) is not None else m.group(2)
        var = braced
        if var is None:
            return m.group(0)
        if var.isdigit():
            idx = int(var)
            if script_args and 1 <= idx <= len(script_args):
                return script_args[idx - 1]
            return ""
        # env vars plus builtins
        if var in os.environ:
            return os.environ[var]
        if var == "HOME":
            return os.environ.get("HOME", "")
        return os.environ.get(var, "")
    return re.sub(r"\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*|\d+)", repl, text)

