    def write_out(self, s):
        if self.redirect_fh is not None:
            try:
                self.redirect_fh.write(s)
                self.redirect_fh.flush()
            except Exception:
                pass
            return
        try:
            self.out.write(s)
        except (BrokenPipeError, UnicodeEncodeError):
            try:
                self.out.buffer.write(s.encode("utf-8", errors="surrogateescape"))
            except Exception:
                pass

    def write_err(self, s):
        try:
            self.err.write(s)
        except Exception:
            pass

    def error_with_help(self, first_line, cmdname, orig_cmd, extra_lines=""):
        # first_line like '  error: ...\n' (or with reason lines included in extra)
        msg = first_line
        if extra_lines:
            msg += extra_lines
        msg += f" --> {self.cmd_source}:{self.cmd_index}\n"
        msg += f" | {orig_cmd.strip()}" + " " * max(1, 40 - len(orig_cmd.strip())) + "\n" if False else f" | {pad_cmd_line(orig_cmd)}\n"
        msg += command_help_block(cmdname)
        self.write_err(msg)

