    def _init_db(self):
        con = sqlite3.connect(":memory:")
        con.text_factory = str
        self.db = con
        # collations
        def loglevel_collate(a, b):
            ra = LEVEL_RANK.get(str(a).lower() if a is not None else "", -1)
            rb = LEVEL_RANK.get(str(b).lower() if b is not None else "", -1)
            # 'warn' alias
            if str(a).lower() == "warn":
                ra = LEVEL_RANK["warning"]
            if str(b).lower() == "warn":
                rb = LEVEL_RANK["warning"]
            return (ra > rb) - (ra < rb) if (ra != -1 or rb != -1) else ((a or "") > (b or "")) - ((a or "") < (b or ""))
        def natural_key(s):
            return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", str(s or ""))]
        def natural_collate(a, b):
            ka, kb = natural_key(a), natural_key(b)
            return (ka > kb) - (ka < kb)
        def ip_collate(a, b):
            def key(s):
                parts = re.split(r"[.:]", str(s or ""))
                out = []
                for p in parts:
                    out.append((0, int(p)) if p.isdigit() else (1, p))
                return out
            ka, kb = key(a), key(b)
            return (ka > kb) - (ka < kb)
