            if sample_msg is None:
                params.append(None)
                continue
            # Validate column exists in all_logs or message fields or format schema
            if not self._is_known_column(n):
                errname = n
            v = self._msg_column_value(sample_msg, n, "all_logs", None)
            if v is None and n in sample_msg.fields:
                v = sample_msg.fields.get(n)
            params.append(v)
        return sql, params, errname

    def _is_known_column(self, n):
        known = {"log_line", "log_time", "log_level", "log_body", "log_text", "log_path",
                 "log_part", "log_mark", "log_comment", "log_tags", "log_format"}
        if n in known:
            return True
        for cols in self.schema_tables.values():
            if n in [c[0] for c in cols]:
                return True
        return False

    def validate_col_expr(self, expr):
        """Return error column name or None. Mimics 'no such column: log_level' when colon missing."""
        # If expr references bare identifiers that are columns without colon, sqlite would error.
        # Reference: :filter-expr log_level = 'error' -> "no such column: log_level".
        # So: attempt to compile SELECT (<expr with :col -> NULL>) ; bare column names will fail.
        names = re.findall(r":([A-Za-z_][A-Za-z0-9_]*)", expr)
        for n in names:
            if not self._is_known_column(n):
                return n
        sql = re.sub(r":([A-Za-z_][A-Za-z0-9_]*)", "NULL", expr)
        try:
            self.db.execute(f"SELECT ({sql})")
        except sqlite3.OperationalError as e:
            msg = str(e)
            m = re.search(r"no such column:\s*(\S+)", msg)
            return m.group(1) if m else msg
        except Exception as e:
            return str(e)
        return None

