        lines = []
        for lf in self.files:
            if lf.filepath in self.hidden_files:
                continue
            if lf.is_text:
                lines.extend(lf.lines)
        return lines

    def current_view_lines(self):
        view = self.current_view()
        if view == "db":
            if self.last_query:
                cols, rows = self.last_query
                txt = format_table(cols, rows)
                return txt.splitlines()
            return []
        if view == "help":
            return data_text("help.txt", "").splitlines()
        if view == "text":
            return self.text_view_lines()
        if view == "pretty":
            # pretty view approximates log view display
            return [l for m in self.visible_messages() for l in m.text.split("\n")]
        if view == "schema":
            return data_text("schema.txt", "").splitlines()
        if view in ("histogram", "spectro", "timeline"):
            return []
        # log view default: if no log messages but text files exist, reference prints text lines
        # (it starts in text-capable mode). Our headless default print handles that separately;
        # here return log lines with metadata annotations.
        out = []
        for m in self.visible_messages():
            lines = m.text.split("\n")
            out.extend(lines)
            meta = []
            if m.comment:
                meta.append(m.comment)
            if m.tags:
                for t in m.tags:
                    meta.append("#" + t.lstrip("#"))
            if meta:
                out.append(f"▌ Line {m.line_no} metadata")
                for entry in meta:
                    out.append(f" └ {entry}")
