    def default_headless_output(self):
        view = self.current_view()
        # If redirect active, final output goes there (observed: :sh output after redirect went to file)
        # If last action was SQL in db view, print table; if log view with messages, print them;
        # if only text files, print text; if help view, print help.
        if view == "db" and self.last_query is not None:
            cols, rows = self.last_query
            self.write_out(format_table(cols, rows))
            return
        if view == "help":
            self.write_out(data_text("help.txt", ""))
            return
        if view == "text":
            for l in self.text_view_lines():
                self.write_out(l + "\n")
            return
        if view == "log":
            vis = self.visible_messages()
            if vis:
                top = self.view_tops.get("log", 0)
                for m in vis[top:]:
                    # Each message text may be multiline; write lines + metadata
                    self.write_out(m.text + "\n" if not m.text.endswith("\n") else m.text)
                    meta = []
                    if m.comment:
                        meta.append(m.comment)
                    if m.tags:
                        for t in m.tags:
                            meta.append("#" + str(t).lstrip("#"))
                    if meta:
                        self.write_out(f"▌ Line {m.line_no} metadata\n")
                        for e in meta:
                            self.write_out(f" └ {e}\n")
                return
            # No log messages: fall back to text files / empty
            text_lines = []
            for lf in self.files:
                if lf.filepath in self.hidden_files:
                    continue
                if lf.is_text:
                    text_lines.extend(lf.lines)
            for l in text_lines:
                self.write_out(l + "\n")
            return
        # other views: print current view lines
        for l in self.current_view_lines():
            self.write_out(l + "\n")

