            if expanded:
                for e in expanded:
                    _open_one(sess, e, orig)
                continue
            msg = (f"  error: cannot open file: {pth}\n reason: No such file or directory\n"
                   f" --> {sess.cmd_source}:{sess.cmd_index}\n | {pad_cmd_line(orig)}\n"
                   f" = help: make sure the file exists and is accessible\n")
            sess.write_err(msg)
