                    continue
                gd = mm.groupdict()
                row_map = {"log_line": m.line_no, "log_time": fmt_log_time(m.time), "log_level": m.level,
                           "log_part": m.part, "log_idle_msecs": m.idle_msecs, "log_mark": int(bool(m.mark)),
                           "log_comment": m.comment, "log_tags": None, "log_annotations": None, "log_filters": None}
                for g in groups:
                    row_map[g] = gd.get(g)
                row = tuple(row_map.get(c) for c, _ in allcols)
                sess.db.execute(f'INSERT INTO "{tname}" VALUES ({",".join("?" for _ in allcols)})', row)
        sess.db.commit()
    except Exception:
        pass

def h_delete_search_table(sess, name, args, args_raw, orig):
