def _sess_exec_any(self, cmdline, orig_for_errors=None):
    cmdline = cmdline.strip("\n")
    stripped = cmdline.lstrip()
    if not stripped:
        return
    if stripped.startswith("#"):
        return
    orig = orig_for_errors or stripped
    first = stripped[0]
    if first == ":":
        self.exec_colon(stripped, orig)
    elif first == ";":
        self.exec_sql_cmd(stripped, orig)
    elif first == "|":
        self.exec_script_cmd(stripped, orig)
    else:
        # In script files, lines without prefix? Reference script files require prefixes too.
        # Treat as error? For robustness, ignore comments handled above; else try colon?
        self.write_err(f"  error: unknown command: “{stripped.split()[0]}”\n")
        self._had_error = True

Session.exec_any = _sess_exec_any

