# --- config handling ---

def load_effective_config():
    base = data_text("config_get.json", "{}")
    try:
        cfg = json.loads(base)
    except Exception:
        cfg = {}
    # Merge user config.json overrides (simple deep merge for clock-format etc.)
    hd = home_dir()
    user_path = os.path.join(hd, "config.json")
    user = {}
    try:
        with open(user_path, "r", encoding="utf-8") as fh:
            user = json.load(fh)
    except Exception:
        user = {}
    def deep_merge(dst, src):
        for k, v in src.items():
            if isinstance(v, dict) and isinstance(dst.get(k), dict):
                deep_merge(dst[k], v)
            else:
                dst[k] = v
    if user:
        deep_merge(cfg, user)
    return cfg, user

def config_get_path(cfg, path):
    # path like /ui/clock-format
    parts = [p for p in path.split("/") if p]
    cur = cfg
    for p in parts:
        if isinstance(cur, dict) and p in cur:
            cur = cur[p]
        else:
            return (False, None)
    return (True, cur)

def config_set_path(user, path, value_str):
    parts = [p for p in path.split("/") if p]
    cur = user
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    # value: try JSON parse, else string as-is (reference stored '"%Y"' with quotes kept as part of string when passed quoted? Probe: :config /ui/clock-format "%Y" -> stored "\"%Y\"" meaning value string includes quotes. Our args after shlex? We receive raw args: '/ui/clock-format "%Y"' -> value part is '"%Y"' including quotes. Stored value was '"%Y"' (string with quotes). And get printed '"/ui/... = "\\"%Y\\""' i.e. json.dumps of that. So store raw token string verbatim.
    cur[parts[-1]] = value_str

def save_user_config(user):
    hd = home_dir()
    # Reference config.json contains more than just the set key (theme-defs etc. materialized).
    # We preserve existing file content merged: load existing, apply user dict (which is existing based).
    path = os.path.join(hd, "config.json")
    try:
        os.makedirs(hd, exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(user, fh, indent=4)
