    if len(parts) == 1:
        sess.write_out(f"{path} = {json.dumps(cur_val)}\n")
        sess._wrote_to_stdout = True
        # Reference: :config get printed and (with -N no file) nothing else. With file? unknown suppression. Mark direct so driver suppresses default? Probe config tests used -nN (no default). We'll suppress default when config output printed.
        sess._direct_output_done = True
