def h_summarize(sess, name, args, args_raw, orig):
    col = args.strip().split()[0] if args.strip() else ""
    if sess.current_view() == "db" and sess.last_query:
        cols, rows = sess.last_query
        if col in cols:
            idx = cols.index(col)
            from collections import Counter
            counts = Counter(r[idx] for r in rows)
            new_cols = [f"c_{col}", f"count_{col}"]
            new_rows = [(k, counts[k]) for k in counts]
            sess.last_query = (new_cols, new_rows)
            return
    # Log view summarize: count by column via SQL on all_logs? Approximate with messages.
    from collections import Counter
    counts = Counter()
    for m in sess.visible_messages():
        v = sess._msg_column_value(m, col, "all_logs", None)
        if v is None and col in m.fields:
            v = m.fields[col]
        counts[v] += 1
    sess.last_query = ([f"c_{col}", f"count_{col}"], [(k, counts[k]) for k in counts])
    if sess.current_view() != "db":
        sess.view_stack.append("db")

