def h_create_search_table(sess, name, args, args_raw, orig):
    parts = args_raw.split(None, 1)
    if not parts:
        return
    tname = parts[0]
    pattern = parts[1] if len(parts) > 1 else ""
    sess.search_tables[tname] = pattern
    # Create table with search results: columns from named groups or generic
    groups = []
    try:
        rx = re.compile(_convert_pattern(pattern)) if pattern else None
        if rx:
            groups = [g for g in rx.groupindex.keys()]
    except Exception:
        rx = None
    base_cols = [("log_line", "INTEGER"), ("log_time", "DATETIME"), ("log_level", "TEXT")]
    extra = [(g, "TEXT") for g in groups if g not in ("timestamp", "body")]
    allcols = base_cols + extra + [("log_part", "TEXT"), ("log_idle_msecs", "INTEGER"),
                                    ("log_mark", "BOOLEAN"), ("log_comment", "TEXT"),
                                    ("log_tags", "TEXT"), ("log_annotations", "TEXT"), ("log_filters", "TEXT")]
    try:
        sess.db.execute(f'DROP TABLE IF EXISTS "{tname}"')
        defs = ", ".join(f'"{c}" {t}' for c, t in allcols)
        sess.db.execute(f'CREATE TABLE "{tname}" ({defs})')
        if rx:
            for m in sess.messages:
                mm = rx.search(m.text)
                if not mm:
                    continue
                gd = mm.groupdict()
                row_map = {"log_line": m.line_no, "log_time": fmt_log_time(m.time), "log_level": m.level,
                           "log_part": m.part, "log_idle_msecs": m.idle_msecs, "log_mark": int(bool(m.mark)),
                           "log_comment": m.comment, "log_tags": None, "log_annotations": None, "log_filters": None}
                for g in groups:
                    row_map[g] = gd.get(g)
                row = tuple(row_map.get(c) for c, _ in allcols)
                sess.db.execute(f'INSERT INTO "{tname}" VALUES ({",".join("?" for _ in allcols)})', row)
        sess.db.commit()
    except Exception:
        pass

def h_delete_search_table(sess, name, args, args_raw, orig):
