                fh.write("# lnav session\n")
        except OSError:
            pass

def h_set_file_timezone(sess, name, args, args_raw, orig):
    zone = args.strip().split()[0] if args.strip() else ""
    # Reference requires system zoneinfo; in this environment it fails with discover_tz_dir error.
    # Check if /usr/share/zoneinfo exists - if not, reproduce error for any zone.
    if not os.path.isdir("/usr/share/zoneinfo"):
        # Note: command_help description wraps differently in reference for this command
        # ("Set the timezone to use..." two lines + third "glob pattern.")
        msg = (f'  error: “{zone}” is not a valid timezone\n reason: discover_tz_dir failed to find zoneinfo\n'
               f' --> {sess.cmd_source}:{sess.cmd_index}\n | {pad_cmd_line(orig)}\n')
        msg += command_help_block(name)
        sess.write_err(msg)
        sess._had_error = True
        sess._direct_output_done = True
        return
    # With zoneinfo present, accept UTC and known zones, else error similarly (simplified)
    if zone not in ("UTC", "GMT") and not os.path.exists(os.path.join("/usr/share/zoneinfo", zone)):
        msg = (f'  error: “{zone}” is not a valid timezone\n'
               f' --> {sess.cmd_source}:{sess.cmd_index}\n | {pad_cmd_line(orig)}\n')
        msg += command_help_block(name)
        sess.write_err(msg)
        sess._had_error = True
        sess._direct_output_done = True

