def h_hide_show_fields(sess, name, args, args_raw, orig):
    fields = args_raw.split()
    # Known fields depend on current log formats present. In DB view, reference said unknown for log_level.
    # In log view, fields are format value names. Validate:
    known = set()
    if sess.current_view() == "log":
        for lf in sess.files:
            fmt = sess.formats.get(lf.format_name) if lf.format_name else None
            if fmt:
                known.update(fmt.value_defs.keys())
    unknown = [f for f in fields if f not in known]
    if unknown:
        _cmd_error(sess, name, orig, f"unknown field(s) -- {unknown[0]}")
        return
    # known: no visual effect headless (could affect display text; ignore)

