def _is_glob(s):
    return any(c in s for c in "*?[")

def _rotated_files(path):
    # path, path.1, path.2.gz, path-YYYY... etc sorted oldest? Reference -R loads older rotated.
    results = []
    directory = os.path.dirname(os.path.abspath(path)) or "."
    base = os.path.basename(path)
    try:
        entries = os.listdir(directory)
    except OSError:
        return results
    pats = [
        re.compile(r"^" + re.escape(base) + r"\.(\d+)(?:\.(?:gz|bz2|xz))?$"),
        re.compile(r"^" + re.escape(base) + r"-(\d{8,14})(?:\.(?:gz|bz2|xz))?$"),
    ]
    rot = []
    for e in entries:
        for p in pats:
            m = p.match(e)
            if m:
                rot.append((m.group(1), os.path.join(directory, e)))
                break
    rot.sort(key=lambda x: x[0], reverse=True)  # higher number = older first? merged sort by time fixes order anyway
    return [p for _, p in rot]

