        return 107
    hd = home_dir()
    # 'extra' special: try git clone (will fail offline, reproducing reference messages)
    for f in files:
        if f == "extra":
            sys.stdout.write("Cloning lnav remote config repo...\n")
            dest = os.path.join(hd, "remote-config")
            try:
                p = subprocess.run(["git", "clone", "https://github.com/tstack/lnav-config.git", dest],
                                   capture_output=True, text=True, timeout=20)
                if p.stderr:
                    sys.stderr.write(p.stderr)
                if p.stdout:
                    sys.stdout.write(p.stdout)
            except Exception as e:
                sys.stderr.write(f"fatal: unable to access 'https://github.com/tstack/lnav-config.git/': {e}\n")
            if not os.path.exists(os.path.join(dest, "remote-config.json")):
                sys.stderr.write("Unable to open remote-config.json: No such file or directory\n")
            return 0
        # URL handling: git repos? If ends with .git or starts http - attempt clone into staging? Simplified: treat as file.
        if not os.path.exists(f):
            sys.stderr.write(f"  error: unable to open configuration file: {f}\n reason: No such file or directory\n")
            return 1
        try:
            with open(f, "rb") as fh:
                raw = fh.read()
        except OSError as e:
            sys.stderr.write(f"  error: unable to open configuration file: {f}\n reason: {e.strerror or e}\n")
            return 1
        try:
            doc = json.loads(raw.decode("utf-8", errors="replace"))
        except Exception as e:
            # Reference JSON error format (lexical error with snippet). Approximate for non-JSON text:
            text_snippet = raw.decode("utf-8", errors="replace")[:47].split("\n")[0]
            sys.stderr.write(f"  error: unable to open configuration file: {f}\n reason: JSON parsing failed -- lexical error: invalid char in json text.\n |                                               {text_snippet}\n |                            (right here) ------^\n")
            return 1
        # Install each format key as <key>.json into formats/installed
        installed_dir = os.path.join(hd, "formats", "installed")
        os.makedirs(installed_dir, exist_ok=True)
        fmt_keys = [k for k in doc.keys() if k != "$schema"] if isinstance(doc, dict) else []
        if not fmt_keys:
            # Could be a config/json without format? Install file as-is with basename
            dest_name = os.path.basename(f)
            dest = os.path.join(installed_dir, dest_name)
            with open(dest, "wb") as out:
                out.write(raw)
            sys.stdout.write(f"  installed -- {dest}\n")
            continue
        for k in fmt_keys:
            dest = os.path.join(installed_dir, f"{k}.json")
            with open(dest, "wb") as out:
                out.write(raw)
            sys.stdout.write(f"  installed -- {dest}\n")
    return 0

def run_check(opts):
    formats = load_formats(opts.get("includes"))
    rc = 0
    for f in opts["files"]:
        if not os.path.exists(f):
            sys.stderr.write(f"  error: unable to open file: {f}\n reason: No such file or directory\n")
            rc = 1
            continue
        if os.path.isdir(f):
            continue
        try:
            data = read_file_bytes(f)
            lines = decode_lines(data)
        except OSError as e:
            sys.stderr.write(f"  error: unable to open file: {f}\n reason: {e.strerror or e}\n")
            rc = 1
            continue
        fmt_name, fmt = detect_format(lines, formats, os.path.abspath(f))
        if fmt_name is None or (fmt is None and fmt_name != "__json_generic__"):
            sys.stderr.write(f"error:{f}:no format found for file\n")
            rc = 1
        elif not lines:
            sys.stderr.write(f"error:{f}:no format found for file\n")
            rc = 1
    return rc

